// Meteor Dodge game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

// Ship
const ship = {x: canvas.width/2, y: canvas.height-40, w: 40, h: 20, speed: 5};
let left = false, right = false, shoot = false;

// Bullets
const bullets = [];
const bulletSpeed = 7;

// Meteors
const meteors = [];
const meteorMinSpeed = 2, meteorMaxSpeed = 5;
let spawnTimer = 0;
const spawnInterval = 60; // frames

function keyDown(e){if(e.key==='ArrowLeft') left=true; if(e.key==='ArrowRight') right=true; if(e.key===' ' ) shoot=true;}
function keyUp(e){if(e.key==='ArrowLeft') left=false; if(e.key==='ArrowRight') right=false; if(e.key===' ') shoot=false;}
window.addEventListener('keydown',keyDown);
window.addEventListener('keyup',keyUp);

function spawnMeteor(){
  const size = 30 + Math.random()*20;
  meteors.push({x: Math.random()*(canvas.width-size), y:-size, w:size, h:size, speed: meteorMinSpeed + Math.random()*(meteorMaxSpeed-meteorMinSpeed)});
}

function update(){
  // ship movement
  if(left) ship.x -= ship.speed;
  if(right) ship.x += ship.speed;
  ship.x = Math.max(0, Math.min(canvas.width-ship.w, ship.x));

  // shooting
  if(shoot){
    // simple rate limit
    if(bullets.length===0 || bullets[bullets.length-1].y < ship.y-20){
      bullets.push({x: ship.x+ship.w/2, y: ship.y, w:4, h:10});
    }
  }

  // update bullets
  for(let i=bullets.length-1;i>=0;i--){
    bullets[i].y -= bulletSpeed;
    if(bullets[i].y < 0) bullets.splice(i,1);
  }

  // spawn meteors
  if(spawnTimer<=0){spawnMeteor(); spawnTimer=spawnInterval;}
  else spawnTimer--;

  // update meteors
  for(let i=meteors.length-1;i>=0;i--){
    const m=meteors[i];
    m.y += m.speed;
    // check collision with ship
    if(m.x < ship.x+ship.w && m.x+m.w > ship.x && m.y < ship.y+ship.h && m.y+m.h > ship.y){
      alert('Game Over!');
      document.location.reload();
    }
    // check collision with bullets
    for(let j=bullets.length-1;j>=0;j--){
      const b=bullets[j];
      if(m.x < b.x+b.w && m.x+m.w > b.x && m.y < b.y+b.h && m.y+m.h > b.y){
        meteors.splice(i,1);
        bullets.splice(j,1);
        break;
      }
    }
    // remove off‑screen meteors
    if(m.y>canvas.height) meteors.splice(i,1);
  }
}

function draw(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  // ship
  ctx.fillStyle='white';
  ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
  // bullets
  ctx.fillStyle='yellow';
  bullets.forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h));
  // meteors
  ctx.fillStyle='red';
  meteors.forEach(m=>ctx.fillRect(m.x,m.y,m.w,m.h));
}

function loop(){
  update();
  draw();
  requestAnimationFrame(loop);
}
loop();
